constexpr int64_t ONE_REPEAT_SORT_NUM = 32;

at::Tensor sort_float(const at::Tensor& x, int64_t dim, bool descending)
{
    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
    TORCH_CHECK(dim >= 0 && dim < x.dim(), "dim out of range");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int64_t ndim = x.dim();
    int64_t sortDimSize = x.size(dim);
    int64_t outerSize = 1;
    for (int64_t d = 0; d < ndim; d++) {
        if (d != dim) {
            outerSize *= x.size(d);
        }
    }
    int64_t totalLength = outerSize * sortDimSize;

    // Determine dtype
    auto dtype = x.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
