#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
constexpr float MIN_FP32 = -3.402823466e+38f;

struct SortTiling {
    int64_t sortDimSize;
    int64_t alignedSize;
    int64_t outerSize;
    int64_t totalLength;
    int64_t needCoreNum;
    int64_t perCoreRows;
    bool descending;
};

extern "C" __global__ __aicore__ void sort_float(
    GM_ADDR x, GM_ADDR out, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AIC) {
        return;
    }

    auto* gmTiling = reinterpret_cast<__gm__ SortTiling*>(tiling);
    SortTiling t;
    t.sortDimSize = gmTiling->sortDimSize;
    t.alignedSize = gmTiling->alignedSize;
    t.outerSize = gmTiling->outerSize;
    t.totalLength = gmTiling->totalLength;
    t.needCoreNum = gmTiling->needCoreNum;
    t.perCoreRows = gmTiling->perCoreRows;
    t.descending = gmTiling->descending;

    TPipe pipe;
    int64_t sortNum = t.alignedSize;

    // GlobalTensors for GM access
    GlobalTensor<float> xGm;
    xGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x), t.totalLength);
    GlobalTensor<float> outGm;
    outGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(out), t.totalLength);

    // UB: input queue (one row, float32)
    TQue<QuePosition::VECIN, 1> inQueue;
    pipe.InitBuffer(inQueue, 1, sortNum * sizeof(float));

    // UB: output queue (one row, float32)
    TQue<QuePosition::VECOUT, 1> outQueue;
    pipe.InitBuffer(outQueue, 1, sortNum * sizeof(float));

    // UB: temp buffer for Sort
    TBuf<TPosition::VECCALC> tmpBuf;
    pipe.InitBuffer(tmpBuf, sortNum * sizeof(float));

    // UB: sorted buffer
    TBuf<TPosition::VECCALC> sortedBuf;
    pipe.InitBuffer(sortedBuf, sortNum * sizeof(float) * 2);

    // Compute core row range
    int64_t coreId = GetBlockIdx();
    int64_t coreStart = coreId * t.perCoreRows;
    int64_t coreEnd = t.outerSize;
    if (coreEnd > coreStart + t.perCoreRows) {
        coreEnd = coreStart + t.perCoreRows;
    }
    if (coreEnd <= coreStart) {
        return;
    }
    int64_t coreRows = coreEnd - coreStart;

    for (int64_t r = 0; r < coreRows; r++) {
        int64_t rowIdx = coreStart + r;
        int64_t rowStart = rowIdx * t.sortDimSize;

        // === CopyIn: load one row from GM ===
        LocalTensor<float> inLocal = inQueue.AllocTensor<float>();
        DataCopyExtParams copyParams{
            static_cast<uint16_t>(1),
            static_cast<uint32_t>(t.sortDimSize * sizeof(float)),
            0, 0, 0};
        DataCopyPadExtParams copyPadParams{false, 0, 0, 0};
        DataCopyPad(inLocal[0], xGm[rowStart], copyParams, copyPadParams);
        inQueue.EnQue(inLocal);

        // === SortCompute ===
        LocalTensor<float> dataLocal = inQueue.DeQue<float>();

        // Negate for ascending sort
        if (!t.descending) {
            Muls(dataLocal, dataLocal, -1.0f, t.sortDimSize);
        }

        // Pad tail for 32-element alignment using fill
        int64_t duplicateNum = t.sortDimSize % ONE_REPEAT_SORT_NUM;
        if (duplicateNum > 0) {
            int64_t padStart = t.sortDimSize - duplicateNum;
            // Fill the padding area with MIN_FP32
            // We fill from padStart to sortNum (the aligned size)
            // But fill only the tail portion: duplicateNum elements
            // Use Duplicate API for mask-based fill
            uint64_t mask0 = UINT64_MAX;
            mask0 = mask0 << duplicateNum;
            uint64_t maskArr[2] = {mask0, 0};
            Duplicate(dataLocal[padStart], MIN_FP32, maskArr, 1, 1, 8);
        }

        // Hardware Sort
        LocalTensor<float> sortedLocal = sortedBuf.Get<float>(sortNum * 2);
        uint32_t calCount = static_cast<uint32_t>(sortNum / ONE_REPEAT_SORT_NUM);
        Sort<float>(sortedLocal, dataLocal, calCount);

        // Extract values from sorted output and write to output queue
        LocalTensor<float> outLocal = outQueue.AllocTensor<float>();

        if (t.descending) {
            // For descending sort: sorted values are at even positions
            // Use vector copy for first element, then loop for rest
            // Actually, use a simple approach: copy sorted values directly
            // if Sort produces clean output. Otherwise, extract from interleaved.
            // For now: use scalar-style element assignment via vector extract
            for (int64_t i = 0; i < t.sortDimSize; i++) {
                outLocal[i] = sortedLocal[2 * i];
            }
        } else {
            // For ascending sort: negate values back
            // Use Muls on the sorted output
            // But Muls operates on the whole buffer, not selected elements
            // For simplicity: use scalar negation
            for (int64_t i = 0; i < t.sortDimSize; i++) {
                outLocal[i] = -sortedLocal[2 * i];
            }
        }

        outQueue.EnQue(outLocal);
        inQueue.FreeTensor(dataLocal);

        // === CopyOut: write one row to GM ===
        LocalTensor<float> outResult = outQueue.DeQue<float>();
        DataCopyParams outParams;
        outParams.blockCount = 1;
        outParams.blockLen = t.sortDimSize * sizeof(float);
        DataCopyPad(outGm[rowStart], outResult[0], outParams);
        outQueue.FreeTensor(outResult);
    }
}
