#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
constexpr float MIN_FP32 = -3.402823466e+38f;

struct SortTiling {
    int64_t sortDimSize;
    int64_t alignedSize;
    int64_t outerSize;
    int64_t totalLength;
    int64_t needCoreNum;
    int64_t perCoreRows;
    bool descending;
};

extern "C" __global__ __aicore__ void sort_float(
    GM_ADDR x, GM_ADDR out, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AIC) {
        return;
    }

    auto* gmTiling = reinterpret_cast<__gm__ SortTiling*>(tiling);
    SortTiling t;
    t.sortDimSize = gmTiling->sortDimSize;
    t.alignedSize = gmTiling->alignedSize;
    t.outerSize = gmTiling->outerSize;
    t.totalLength = gmTiling->totalLength;
    t.needCoreNum = gmTiling->needCoreNum;
    t.perCoreRows = gmTiling->perCoreRows;
    t.descending = gmTiling->descending;

    TPipe pipe;
    int64_t sortNum = t.alignedSize;
    uint32_t calCount = static_cast<uint32_t>(sortNum / ONE_REPEAT_SORT_NUM);

    // UB: input queue (one row, float32)
    TQue<QuePosition::VECIN, 1> inQueue;
    pipe.InitBuffer(inQueue, 1, sortNum * sizeof(float));

    // UB: output queue (one row, float32)
    TQue<QuePosition::VECOUT, 1> outQueue;
    pipe.InitBuffer(outQueue, 1, sortNum * sizeof(float));

    // Compute core row range
    int64_t coreId = GetBlockIdx();
    int64_t coreStart = coreId * t.perCoreRows;
    int64_t coreEnd = t.outerSize;
    if (coreEnd > coreStart + t.perCoreRows) {
        coreEnd = coreStart + t.perCoreRows;
    }
    if (coreEnd <= coreStart) {
        return;
    }
    int64_t coreRows = coreEnd - coreStart;

    for (int64_t r = 0; r < coreRows; r++) {
        int64_t rowIdx = coreStart + r;
        int64_t rowStart = rowIdx * t.sortDimSize;

        // Per-row GlobalTensors
        GlobalTensor<float> xRow;
        xRow.SetGlobalBuffer((__gm__ float*)(x) + rowStart, t.sortDimSize);
        GlobalTensor<float> outRow;
        outRow.SetGlobalBuffer((__gm__ float*)(out) + rowStart, t.sortDimSize);

        // === CopyIn: load one row from GM ===
        LocalTensor<float> inLocal = inQueue.AllocTensor<float>();
        DataCopyParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(t.sortDimSize * sizeof(float));
        DataCopyPadParams padParams;
        DataCopyPad(inLocal[0], xRow, copyParams, padParams);
        inQueue.EnQue(inLocal);

        // === Process: just pass through (NO SORT) for debugging ===
        LocalTensor<float> dataLocal = inQueue.DeQue<float>();
        LocalTensor<float> outLocal = outQueue.AllocTensor<float>();

        // Copy input to output (debug: verify data path)
        // Use Muls with 1.0f to simulate pass-through
        Muls(outLocal, dataLocal, 1.0f, t.sortDimSize);

        outQueue.EnQue(outLocal);
        inQueue.FreeTensor(dataLocal);

        // === CopyOut: write to GM ===
        LocalTensor<float> outResult = outQueue.DeQue<float>();
        DataCopyParams outParams;
        outParams.blockCount = 1;
        outParams.blockLen = static_cast<uint32_t>(t.sortDimSize * sizeof(float));
        DataCopyPad(outRow, outResult[0], outParams);
        outQueue.FreeTensor(outResult);
    }
}
