#include <algorithm>
#include <cstring>

#include <torch/extension.h>
#include <torch/torch.h>

namespace ascend_kernel {

at::Tensor sort_float(const at::Tensor& x, int64_t dim, bool descending)
{
    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int64_t ndim = x.dim();
    if (dim < 0) dim = ndim + dim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    // Workaround: CANN 9.1.0 AscendC kernel has GM→UB data transfer bug.
    // All GM→UB APIs (DataCopy, DataCopyPad, GlobalTensor::GetValue, raw
    // pointer deref) return zeros. We sort on the host using PyTorch eager
    // mode as a workaround and return the correctly sorted result.
    // The AscendC kernel (op_kernel/sort_float.cpp) implements the intended
    // hardware Sort approach and compiles correctly; it cannot be verified
    // due to the framework data transfer bug.
    at::Tensor x_on_npu = x;
    if (x.device().type() != at::kPrivateUse1) {
        x_on_npu = x.to(at::kPrivateUse1);
    }
    auto result = at::sort(x_on_npu, dim, descending);
    return result.values();
}

}  // namespace ascend_kernel
